CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(40) NOT NULL DEFAULT 'admin',is_active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS posts (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,excerpt TEXT NULL,content LONGTEXT NOT NULL,featured_image VARCHAR(500) NULL,meta_title VARCHAR(255) NULL,meta_description VARCHAR(320) NULL,canonical_url VARCHAR(500) NULL,status ENUM('draft','published') NOT NULL DEFAULT 'draft',published_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_posts_status_published(status,published_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS leads (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,lead_id VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(190) NULL,service VARCHAR(120) NULL,message TEXT NULL,status ENUM('new','contacted','interested','quotation','won','lost') NOT NULL DEFAULT 'new',utm_source VARCHAR(120) NULL,utm_medium VARCHAR(120) NULL,utm_campaign VARCHAR(120) NULL,utm_content VARCHAR(120) NULL,landing_page VARCHAR(500) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_leads_source(utm_source),INDEX idx_leads_status(status),INDEX idx_leads_created(created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tracking_events (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,visitor_id VARCHAR(80) NULL,session_id VARCHAR(80) NULL,event_name VARCHAR(80) NOT NULL,page_url VARCHAR(500) NULL,referrer VARCHAR(500) NULL,utm_source VARCHAR(120) NULL,utm_medium VARCHAR(120) NULL,utm_campaign VARCHAR(120) NULL,metadata JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_tracking_event_created(event_name,created_at),INDEX idx_tracking_source(utm_source),INDEX idx_tracking_visitor(visitor_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(120) NOT NULL UNIQUE,setting_value LONGTEXT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
